TableData.java<pre><code>package com.ait.tables;

import java.util.ArrayList;

import javax.annotation.PostConstruct;
import javax.faces.bean.ManagedBean;
import javax.faces.bean.SessionScoped;

@ManagedBean
@SessionScoped
public class TableData {

    private ArrayList&lt;Name&gt; names;

    @PostConstruct
    public void init() {
        names = new ArrayList&lt;Name&gt;();
        Name firstName = new Name("William", "Dupont");
        names.add(firstName);
        Name secondName = new Name("Harry", "Styles");
        names.add(secondName);
        Name thirdName = new Name("Jon", "BonJovi");
        names.add(thirdName);
    }

    public ArrayList&lt;Name&gt; getNames() {
        return names;
    }
}
</code></pre> Last Name First Name Dupont, Williams, Styles, Harry, BonJovi, Jon, Name.java<pre><code>package com.ait.tables;

public class Name {
    private String first;
    private String last;

    public Name(String first, String last) {
        this.first = first;
        this.last = last;
    }

    public String getFirst() {
        return first;
    }

    public void setFirst(String first) {
        this.first = first;
    }

    public String getLast() {
        return last;
    }

    public void setLast(String last) {
        this.last = last;
    }
}
</code></pre> tables.xhtml<pre><code>&lt;!DOCTYPE html PUBLIC "-//W3C//DTD XHTML 1.0 Transitional//EN" "http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd"&gt;
&lt;html xmlns="http://www.w3.org/1999/xhtml"
      xmlns:h="http://java.sun.com/jsf/html"
      xmlns:f="http://java.sun.com/jsf/core"
      xmlns:ui="http://java.sun.com/jsf/facelets"&gt;

&lt;h:head&gt;
    &lt;h:outputStylesheet library="css" name="styles.css" /&gt; &lt;/h:head&gt;
&lt;body&gt;
    &lt;h:form&gt;
        &lt;h:dataTable value="#{tableData.names}" var="name"
                     styleClass="nameTable"
                     headerClass="nameTableHeader"
                     rowClasses="nameTableOddRow,nameTableEvenRow"&gt;
            &lt;h:column&gt;
                &lt;f:facet name="header"&gt;Last Name&lt;/f:facet&gt;
                #{name.last},
            &lt;/h:column&gt;
            &lt;h:column&gt;
                &lt;f:facet name="header"&gt;First Name&lt;/f:facet&gt;
                #{name.first},
            &lt;/h:column&gt;
        &lt;/h:dataTable&gt;
    &lt;/h:form&gt;
&lt;/body&gt;
&lt;/html&gt;
